package com.cvns.service;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.cvns.custom_exceptions.ResourceNotFoundException;import com.cvns.dtos.ResponseDtos.NotificationResponse;import com.cvns.entities.*;import com.cvns.entities.AppEnums.NotificationType;import com.cvns.repository.NotificationRepository;import com.cvns.security.SecurityUtils;import lombok.RequiredArgsConstructor;
@Service @Transactional(readOnly=true) @RequiredArgsConstructor public class NotificationService{private final NotificationRepository repo;private final SecurityUtils sec;@Transactional public Notification create(User u,String title,String message,NotificationType type){if(repo.existsByRecipientIdAndTitleAndMessage(u.getId(),title,message))return null;Notification n=new Notification();n.setRecipient(u);n.setTitle(title);n.setMessage(message);n.setType(type);return repo.save(n);}public List<NotificationResponse> list(){return repo.findByRecipientIdOrderByCreatedAtDesc(sec.currentUser().getId()).stream().map(DtoMapper::notification).toList();}@Transactional public NotificationResponse read(Long id){User u=sec.currentUser();Notification n=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Notification not found"));if(!n.getRecipient().getId().equals(u.getId()))throw new ResourceNotFoundException("Notification not found");n.setRead(true);return DtoMapper.notification(n);}}
